import React from 'react';
import styles from './App.module.scss';
import Home from './pages/Home/Home';
import Circles from './pages/Circles/Circles';

const resolvePageFromPath = (path) => {
  if (path === '/circles') return 'circles';
  return 'home';
};

function App() {
  const [page, setPage] = React.useState(resolvePageFromPath(window.location.pathname));

  React.useEffect(() => {
    const handlePopState = () => {
      setPage(resolvePageFromPath(window.location.pathname));
    };

    window.addEventListener('popstate', handlePopState);
    return () => window.removeEventListener('popstate', handlePopState);
  }, []);

  const navigateTo = (nextPage) => {
    const nextPath = nextPage === 'circles' ? '/circles' : '/';

    if (window.location.pathname !== nextPath) {
      window.history.pushState({}, '', nextPath);
    }

    setPage(nextPage);
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  return (
    <div className={styles.app}>
      {page === 'circles' ? (
        <Circles onNavigate={navigateTo} />
      ) : (
        <Home onNavigate={navigateTo} />
      )}
    </div>
  );
}

export default App;
